// Normalize all 4 sources into a unified lead array
// Sources: gmaps_india, gmaps_intl, meta_india, meta_intl

const gmapsIndia = ($('gmaps-india-batch').first().json.leads || []);
const gmapsIntl  = ($('gmaps-intl-batch').first().json.leads || []);

// Normalize Meta Ads results to the same schema
function normalizeMetaAd(ad, region, country) {
  const waLink = ad.whatsapp_click_to_chat_link || ad.link_url || null;
  let rawPhone = null;
  if (waLink) {
    const phoneMatch = waLink.match(/\d{10,15}/);
    rawPhone = phoneMatch ? phoneMatch[0] : null;
  }
  return {
    business_name: ad.pageName || ad.page_name || '',
    category: ad.category || 'Unknown',
    phone_raw: rawPhone,
    phone_normalized: null, // normalized in next step
    address: null,
    website: ad.link_url || ad.page_website || null,
    has_website: !!(ad.link_url || ad.page_website),
    rating: null,
    review_count: null,
    source: 'meta_ads',
    region: region,
    country: country || 'IN',
    ad_copy: ad.body_text || ad.ad_copy || null,
    original_ad_language: ad.language_detected || ad.language || null,
    is_running_ads: true,
    scraped_at: new Date().toISOString()
  };
}

const metaIndia = ($('apify-meta-india-results').first().json || []).map(ad => normalizeMetaAd(ad, 'india', 'IN'));
const metaIntl  = ($('apify-meta-intl-results').first().json || []).map(ad => {
  // Determine country from page location if available, else default AE
  const country = (ad.country || ad.country_code || 'AE').toUpperCase();
  return normalizeMetaAd(ad, 'intl', country);
});

const allLeads = [...gmapsIndia, ...gmapsIntl, ...metaIndia, ...metaIntl];
console.log(`Total leads collected: ${allLeads.length} (GMaps India: ${gmapsIndia.length}, GMaps Intl: ${gmapsIntl.length}, Meta India: ${metaIndia.length}, Meta Intl: ${metaIntl.length})`);

return allLeads.map(lead => ({ json: lead }));

// Language tagging + preferred_language assignment
const lead = $input.first().json;

// India leads: hinglish unless website/ad copy is purely formal English
let preferred_language = 'english';
if (lead.country === 'IN') {
  // Default India to hinglish; override only if ad copy is purely formal English
  const textToCheck = lead.ad_copy || lead.website_text_excerpt || '';
  // Simple heuristic: if no Devanagari chars and no common Hinglish words, use english
  const hasDevanagari = /[\u0900-\u097F]/.test(textToCheck);
  const hinglishWords = ['aap', 'karo', 'hai', 'hain', 'nahi', 'bahut', 'abhi'];
  const hasHinglish = hinglishWords.some(w => textToCheck.toLowerCase().includes(w));
  preferred_language = (hasDevanagari || hasHinglish) ? 'hinglish' : 'hinglish'; // default hinglish for IN
}

return [{ json: { ...lead, preferred_language } }];

// Merge website enrichment data back onto the lead
const enrichment = $input.first().json;
const lead = $('has-website-check').first().json;

return [{
  json: {
    ...lead,
    website_text_excerpt: enrichment.body_text_excerpt || null,
    has_chat_widget: enrichment.has_chat_widget || false,
    chat_widgets_found: enrichment.chat_widgets_found || [],
    website_title: enrichment.title || null,
    website_fetch_success: enrichment.fetch_success
  }
}];

// Decision-maker lookup via Serper.dev Google X-ray search
// Searches: "[business name]" founder OR owner OR director site:linkedin.com/in
const lead = $input.first().json;

return [{
  json: {
    ...lead,
    serper_query: `"${lead.business_name}" founder OR owner OR director site:linkedin.com/in`
  }
}];

// Parse Serper results to extract LinkedIn profile URL + name
const serperResp = $input.first().json;
const lead = $('build-serper-query').first().json;

let decision_maker_name = null;
let decision_maker_linkedin = null;

try {
  const results = serperResp.organic || [];
  for (const result of results) {
    const url = result.link || '';
    if (url.includes('linkedin.com/in/')) {
      decision_maker_linkedin = url;
      // Extract name from title: "John Smith - Director at Acme | LinkedIn"
      const titleMatch = (result.title || '').match(/^([^-|]+)/);
      if (titleMatch) {
        decision_maker_name = titleMatch[1].trim();
      }
      break;
    }
  }
} catch(e) {
  console.warn('Serper parse error:', e.message);
}

return [{
  json: {
    ...lead,
    decision_maker_name,
    decision_maker_linkedin,
    serper_query: undefined  // clean up temp field
  }
}];

// Build region-aware pain-point detection prompt
const lead = $('parse-serper').first().json;
const leadId = $input.first().json[0]?.id;

const regionalCtx = {
  india: 'WhatsApp is the primary business channel in India. Most SMBs handle enquiries manually, miss leads after hours, and have no follow-up system. Response speed = conversion rate.',
  AE: 'Gulf (UAE): Higher transaction values, owners are decision-makers, WhatsApp widely used professionally.',
  QA: 'Gulf (Qatar): Similar to UAE. WhatsApp + professional networks dominate business communication.',
  SA: 'Saudi Arabia: Relationship-driven business culture. Trust and speed of response are critical.',
  SG: 'Singapore: English-first, efficiency-focused, SMEs care deeply about customer experience quality.'
};
const ctxKey = lead.country === 'IN' ? 'india' : (lead.country || 'AE');
const regionContext = regionalCtx[ctxKey] || regionalCtx['AE'];

const systemPrompt = `You are a B2B sales researcher for VoxAI Agents, a company that builds AI-powered WhatsApp agents, Voice AI agents, and business automation systems for other businesses.

Analyze the following business and identify:
1. Their most likely customer-communication pain point.
2. The single most compelling, specific angle to open a cold outreach conversation.

Regional context for ${lead.country}: ${regionContext}
Do NOT mix regional assumptions across countries.

Respond ONLY in this exact JSON format, no preamble, no trailing text:
{
  "pain_point": "short description (max 20 words)",
  "angle": "specific opening angle referencing something concrete (max 40 words)",
  "confidence": "high | medium | low"
}`;

const userContent = `Business details:
- Name: ${lead.business_name}
- Category: ${lead.category || 'Unknown'}
- Region: ${lead.region} (${lead.country})
- Has website: ${lead.has_website}
- Website summary: ${lead.website_text_excerpt?.substring(0, 500) || 'N/A'}
- Has existing chat widget: ${lead.has_chat_widget || false}
- Running ads: ${lead.is_running_ads || false}
- Ad copy: ${lead.ad_copy?.substring(0, 300) || 'N/A'}
- Rating/reviews: ${lead.rating || 'N/A'} (${lead.review_count || 0} reviews)`;

return [{ json: { lead_id: leadId, lead, system_prompt: systemPrompt, user_content: userContent } }];

const response = $input.first().json;
const rawText = response.choices?.[0]?.message?.content || '';
const prev = $('build-pain-point-prompt').first().json;

let parsed = ;
try {
  const cleaned = rawText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch(e) {
  console.error('Pain-point parse error:', rawText);
  parsed = { pain_point: 'Unable to determine', angle: 'Unable to determine', confidence: 'low' };
}

return [{ json: { ...prev, pain_point: parsed.pain_point || '', angle: parsed.angle || '', confidence: parsed.confidence || 'low' } }];

// Build region + tone aware WhatsApp drafting prompt
const data = $input.first().json;
const lead = data.lead;

const toneMap = {
  IN: "Casual, Hinglish-friendly where natural — like messaging a fellow business owner on WhatsApp, not writing a formal email. Keep it warm and direct.",
  AE: "Professional English, respectful and direct. No slang. Gulf business culture values formality and clarity.",
  QA: "Professional English, respectful and direct. No slang. Gulf business culture values formality and clarity.",
  SA: "Professional English, respectful and direct. Saudi business culture values relationship and trust. Be polite and clear.",
  SG: "Professional English, concise and efficiency-focused. Singapore SMEs value speed and directness."
};
const tone = toneMap[lead.country] || "Professional English.";

const systemPrompt = `Write a short, casual, first-touch WhatsApp outreach message to a business owner.

Rules:
- Under 400 characters total.
- Do NOT open with "Hi, we offer..." or any generic pitch.
- Do NOT mention "AI" or "automation" explicitly.
- Open with something specific referencing their business (use the angle below).
- Ask one question at the end — goal is a reply, not a sale.
- Tone: ${tone}
- Max 1 emoji (optional). No excessive punctuation.
- No company name or URL in the message.

Output ONLY the message text. No quotes, no preamble.`;

const userContent = `Business: ${lead.business_name} (${lead.category}, ${lead.region}, ${lead.country})
Pain point: ${data.pain_point}
Angle: ${data.angle}`;

return [{ json: { ...data, wa_system_prompt: systemPrompt, wa_user_content: userContent } }];

const response = $input.first().json;
const waDraft = (response.choices?.[0]?.message?.content || '').trim();
const prev = $('build-wa-prompt').first().json;
const lead = prev.lead;

// Build wa.me deep link
let waDeepLink = null;
if (lead.phone_normalized) {
  const numericPhone = lead.phone_normalized.replace('+', '');
  waDeepLink = `https://wa.me/${numericPhone}?text=${encodeURIComponent(waDraft)}`;
}

return [{ json: { ...prev, whatsapp_draft: waDraft, whatsapp_deep_link: waDeepLink } }];

// Merge LinkedIn draft (if generated) with the lead data
