let linkedinDraft = null;

try {
  const liResp = $input.first().json;
  linkedinDraft = (liResp.choices?.[0]?.message?.content || '').trim() || null;
} catch(e) 

return [{ json: { ...hasLinkedIn, linkedin_draft: linkedinDraft } }];
